          "contact",
          "address"
        ],
        "type": "object"
      },
      "returns": "Object: { estimate_ref: string, status: logged }",
      "side_effects": "write"
    },
    {
      "auth_scope": "tenant",
      "description": "Notify the front desk / dispatch team (Slack/Teams) that a booking was confirmed or an estimate was logged. Use after a confirmed book_appointment as part of a multi-step workflow.",
      "name": "notify_team",
      "parameters": {
        "properties": {
          "reason": {
            "description": "Why we are notifying, e.g. booking_confirmed, estimate_logged.",
